/usr/bin/bash -lc "node - <<'NODE'
const fs = require('fs');
const path = '/workspace/.exp_agent/round_02/completion.json';
const schemaPath = '/workspace/.exp_agent/round_02/completion-schema.json';
const planPath = '/workspace/.exp_agent/round_02/plan.json';
const data = JSON.parse(fs.readFileSync(path, 'utf8'));
const schema = JSON.parse(fs.readFileSync(schemaPath, 'utf8'));
const plan = JSON.parse(fs.readFileSync(planPath, 'utf8'));
const errors = [];
const required = schema.required;
for (const key of required) if ("'!(key in data)) errors.push(`missing root key ${key}`);
if (JSON.stringify(data.selected_rules) !== JSON.stringify(plan.rules.map(r => r.rule))) errors.push('"'selected_rules do not match plan');
if ("'!Array.isArray(data.blocked) || data.blocked.length !== 0) errors.push('"'blocked is not empty');
if ("'!Array.isArray(data.unresolved_external) || data.unresolved_external.length !== 0) errors.push('"'unresolved_external is not empty');
if ("'!Array.isArray(data.entity_repairs)) errors.push('"'entity_repairs is not an array');
for (const [i, repair] of (data.entity_repairs || []).entries()) {
  for (const key of schema.properties.entity_repairs.items.required) if ("'!(key in repair)) errors.push(`repair ${i} missing ${key}`);
  if (!Array.isArray(repair.locations) || repair.locations.length < 1) errors.push(`repair ${i} locations invalid`);
  if (!Array.isArray(repair.entities) || repair.entities.length < 1 || repair.entities.some(v => typeof v !== '"'string' || "'!v)) errors.push(`repair ${i} entities invalid`);
  if (!Array.isArray(repair.evidence) || repair.evidence.length < 1 || repair.evidence.some(v => typeof v !== '"'string' || "'!v)) errors.push(`repair ${i} evidence invalid`);
  if (repair.status !== '"'repaired') errors.push("'`repair ${i} status invalid`);
  if (typeof repair.transformation !== '"'string' || repair.transformation.length < 1) errors.push("'`repair ${i} transformation invalid`);
  for (const loc of repair.locations || []) if (!Number.isInteger(loc.line) || !Number.isInteger(loc.column)) errors.push(`repair ${i} location invalid`);
}
console.log(JSON.stringify({valid: errors.length === 0, errors}, null, 2));
